        # Returns true if exception messages will be sent to a tty.
        # @return [Boolean]
        def to_tty?; end
        # With no argument, or if the argument is the same as the receiver, return the receiver.
        # @return [Exception]
        def exception(msg = nil); end
      end
    end

    # The global value false is the only instance of class FalseClass and represents a logically false value in boolean expressions.
    class FalseClass
      # @return [TrueClass]
