      # @param arg [FalseClass, nil]
      def ^(arg); end
      # The string representation of false is "false".
      # @return [String]
      def inspect; end
      # The string representation of false is "false".
      # @return [String]
      def to_s; end
      # @param arg [nil, FalseClass]
      def |(arg); end
    end

