      # Return the key caused this KeyError exception.
      # @return [K, nil]
      def key; end
      # Return the receiver associated with this KeyError exception.
      # @return [R, nil]
      def receiver; end
    end

    # Raised when a file required (a Ruby script, extension library, ...) fails to load.
