    # AbstractSyntaxTree provides methods to parse Ruby code into abstract syntax trees.
    module RubyVM::AbstractSyntaxTree
      class << self
        # Parses the given *string* into an abstract syntax tree, returning the root node of that tree.
        # @param string [String]
        # @return [RubyVM::AbstractSyntaxTree::Node]
        def parse(string, keep_script_lines: nil, error_tolerant: nil, keep_tokens: nil); end
        # Reads the file from *pathname*, then parses it like ::parse, returning the root node of the abstract syntax tree.
        # @return [RubyVM::AbstractSyntaxTree::Node]
        def parse_file(string, keep_script_lines: nil, error_tolerant: nil, keep_tokens: nil); end
        # Returns AST nodes of the given *proc* or *method*.
        # @param body [Proc, Method, UnboundMethod]
        # @return [RubyVM::AbstractSyntaxTree::Node, nil]
        def of(body, keep_script_lines: nil, error_tolerant: nil, keep_tokens: nil); end
        # Returns the node id for the given backtrace location.
        # @param backtrace_location [Thread::Backtrace::Location]
        # @return [Integer]
        def node_id_for_backtrace_location(backtrace_location); end
      end
    end

