    # ConditionVariable objects augment class Mutex.
    class Thread::ConditionVariable < Object
      # Wakes up all threads waiting for this lock.
      # @return [self]
      def broadcast; end
      # Wakes up the first thread in line waiting for this lock.
      # @return [self]
      def signal; end
      # Releases the lock held in mutex and waits; reacquires the lock on wakeup.
      # @param mutex [Thread::Mutex]
      # @param timeout [Integer, Float, nil]
      # @return [Integer, nil]
      def wait(mutex, timeout = nil); end
    end

    # Thread::Mutex implements a simple semaphore that can be used to coordinate access to shared data from multiple concurrent threads.
    class Thread::Mutex < Object
      # Attempts to grab the lock and waits if it isn't available.
      # @return [self]
      def lock; end
      # Returns true if this lock is currently held by some thread.
      # @return [Boolean]
      def locked?; end
      # Returns true if this lock is currently held by current thread.
      # @return [Boolean]
      def owned?; end
      # Obtains a lock, runs the block, and releases the lock when the block completes.
      def synchronize(&block); end
      # Attempts to obtain the lock and returns immediately.
      # @return [Boolean]
      def try_lock; end
      # Releases the lock.
      # @return [self]
      def unlock; end
    end

    # The Thread::Queue class implements multi-producer, multi-consumer queues.
    class Thread::Queue < Object
      # Pushes the given object to the queue.
      def <<(obj); end
      # Removes all objects from the queue.
      def clear; end
      # Closes the queue.
      # @return [self]
      def close; end
      # Returns true if the queue is closed.
      # @return [Boolean]
      def closed?; end
      # Retrieves data from the queue.
      def deq(non_block = nil, timeout: nil); end
      # Returns true if the queue is empty.
      # @return [Boolean]
      def empty?; end
      # Pushes the given object to the queue.
      def enq(obj); end
      # Raises an exception: Queue.new.freeze # Raises TypeError (cannot freeze #<Thread::Queue:0x...>)
      def freeze; end
      # Returns the length of the queue.
      # @return [Integer]
      def length; end
      # Returns the number of threads waiting on the queue.
      # @return [Integer]
      def num_waiting; end
      # Retrieves data from the queue.
      def pop(non_block = nil, timeout: nil); end
      # Pushes the given object to the queue.
      def push(obj); end
      # Retrieves data from the queue.
      def shift(non_block = nil, timeout: nil); end
      # Returns the length of the queue.
      # @return [Integer]
      def size; end
    end

    # This class represents queues of specified size capacity.
    class Thread::SizedQueue < Thread::Queue
      # Pushes object to the queue.
      def <<(obj, non_block = nil, timeout:); end
      # Pushes object to the queue.
      def enq(obj, non_block = nil, timeout:); end
      # Raises an exception: Queue.new.freeze # Raises TypeError (cannot freeze #<Thread::Queue:0x...>)
      def freeze; end
      # Creates a fixed-length queue with a maximum size of max.
      # @param max [Integer]
      def initialize(max); end
      # Returns the maximum size of the queue.
      # @return [Integer]
      def max; end
      # Sets the maximum size of the queue to the given number.
      # @param max [Integer]
      def max=(max); end
      # Pushes object to the queue.
      def push(obj, non_block = nil, timeout:); end
    end

