    # ARGF is a stream designed for use in scripts that process files given as command-line arguments or passed in via STDIN.
    class RBS::Unnamed::ARGFClass
      include Enumerable
      # Returns the ARGV array, which contains the arguments passed to your script, one per element.
      # @return [Array<String>]
      def argv; end
      # Puts ARGF into binary mode.
      # @return [self]
      def binmode; end
      # Returns true if ARGF is being read in binary mode; false otherwise.
      # @return [Boolean]
      def binmode?; end
      # Closes the current file and skips to the next file in ARGV.
      # @return [self]
      def close; end
      # Returns *true* if the current file has been closed; *false* otherwise.
      # @return [Boolean]
      def closed?; end
      # Returns an enumerator which iterates over each line (separated by *sep*, which defaults to your platform's newline character) of each file in ARGV.
      # @param sep [String]
      # @param limit [Integer]
      # @yieldparam [String] line
      def each(sep = nil, limit = nil, &block); end
      # Iterates over each byte of each file in ARGV.
      # @yieldparam [Integer] byte
      def each_byte(&block); end
      # Iterates over each character of each file in ARGF.
      # @yieldparam [String] char
      def each_char(&block); end
      # Iterates over each codepoint of each file in ARGF.
      # @yieldparam [Integer] codepoint
      def each_codepoint(&block); end
      # Returns an enumerator which iterates over each line (separated by *sep*, which defaults to your platform's newline character) of each file in ARGV.
      # @param sep [String]
      # @param limit [Integer]
      # @yieldparam [String] line
      def each_line(sep = nil, limit = nil, &block); end
      # Returns true if the current file in ARGF is at end of file, i.e.
      # @return [Boolean]
      def eof; end
      # Returns true if the current file in ARGF is at end of file, i.e.
      # @return [Boolean]
      def eof?; end
      # Returns the external encoding for files read from ARGF as an Encoding object.
      # @return [Encoding]
      def external_encoding; end
      # Returns the current file as an IO or File object.
      # @return [IO, File]
      def file; end
      # Returns the current filename.
      # @return [String]
      def filename; end
      # Returns an integer representing the numeric file descriptor for the current file.
      # @return [Integer]
      def fileno; end
      # Gets the next 8-bit byte (0..255) from ARGF.
      # @return [Integer, nil]
      def getbyte; end
      # Reads the next character from ARGF and returns it as a String.
      # @return [String, nil]
      def getc; end
      # Returns the next line from the current file in ARGF.
      # @param sep [String]
      # @param limit [Integer]
      # @return [String, nil]
      def gets(sep = nil, limit = nil); end
      # Returns the file extension appended to the names of backup copies of modified files under in-place edit mode.
      # @return [String, nil]
      def inplace_mode; end
      # Sets the filename extension for in-place editing mode to the given String.
      # @param arg [String]
      # @return [self]
      def inplace_mode=(arg); end
      # Returns "ARGF".
      # @return [String]
      def inspect; end
      # Returns the internal encoding for strings read from ARGF as an Encoding object.
      # @return [Encoding]
      def internal_encoding; end
      # Returns the current line number of ARGF as a whole.
      # @return [Integer]
      def lineno; end
      # Sets the line number of ARGF as a whole to the given Integer.
      # @param arg [Integer]
      def lineno=(arg); end
      # Returns the current filename.
      # @return [String]
      def path; end
      # Returns the current offset (in bytes) of the current file in ARGF.
      # @return [Integer]
      def pos; end
      # Seeks to the position given by *position* (in bytes) in ARGF.
      # @param arg [Integer]
      # @return [Integer]
      def pos=(arg); end
      # Writes the given objects to the stream; returns nil.
      def print(*args); end
      # Formats and writes objects to the stream.
      # @param format_string [String]
      def printf(format_string, *args); end
      # Writes a character to the stream.
      # @param obj [Numeric, String]
      def putc(obj); end
      def puts(*obj); end
      # Reads *length* bytes from ARGF.
      # @param length [Integer, nil]
      # @param outbuf [String]
      # @return [String, nil]
      def read(length = nil, outbuf = nil); end
      # Reads at most *maxlen* bytes from the ARGF stream in non-blocking mode.
      # @param maxlen [Integer]
      # @param buf [String]
      # @return [String]
      def read_nonblock(maxlen, buf = nil, **options); end
      # Reads the next 8-bit byte from ARGF and returns it as an Integer.
      # @return [Integer]
      def readbyte; end
      # Reads the next character from ARGF and returns it as a String.
      # @return [String]
      def readchar; end
      # Returns the next line from the current file in ARGF.
      # @param sep [String]
      # @param limit [Integer]
      # @return [String]
      def readline(sep = nil, limit = nil); end
      # Reads each file in ARGF in its entirety, returning an Array containing lines from the files.
      # @param sep [String]
      # @param limit [Integer]
      # @return [Array<String>]
      def readlines(sep = nil, limit = nil); end
      # Reads at most *maxlen* bytes from the ARGF stream.
      # @param maxlen [Integer]
      # @param outbuf [String]
      # @return [String]
      def readpartial(maxlen, outbuf = nil); end
      # Positions the current file to the beginning of input, resetting ARGF.lineno to zero.
      # @return [Integer]
      def rewind; end
      # Seeks to offset *amount* (an Integer) in the ARGF stream according to the value of *whence*.
      # @param amount [Integer]
      # @param whence [Integer]
      # @return [Integer]
      def seek(amount, whence = nil); end
      # If single argument is specified, strings read from ARGF are tagged with the encoding specified.
      # @param ext_or_ext_int_enc [String, Encoding]
      # @param int_enc [String, Encoding]
      # @return [self]
      def set_encoding(ext_or_ext_int_enc, int_enc = nil); end
      # Sets the current file to the next file in ARGV.
      # @return [self]
      def skip; end
      # Returns the current offset (in bytes) of the current file in ARGF.
      # @return [Integer]
      def tell; end
      # Reads each file in ARGF in its entirety, returning an Array containing lines from the files.
      # @param sep [String]
      # @param limit [Integer]
      # @return [Array<String>]
      def to_a(sep = nil, limit = nil); end
      # Returns an integer representing the numeric file descriptor for the current file.
      # @return [Integer]
      def to_i; end
      # Returns an IO object representing the current file.
      # @return [IO]
      def to_io; end
      # Returns "ARGF".
      # @return [String]
      def to_s; end
      # Returns IO instance tied to *ARGF* for writing if inplace mode is enabled.
      # @return [IO]
      def to_write_io; end
      # Writes *string* if inplace mode.
      # @return [Integer]
      def write(string); end
      private
      def initialize(*argv); end
      # @param orig [self]
      # @return [self]
      def initialize_copy(orig); end
    end

    # ENV is a hash-like accessor for environment variables.
    class RBS::Unnamed::ENVClass
      include Enumerable
      # Returns the value for the environment variable name if it exists: ENV['foo'] = '0' ENV['foo'] # => "0"
      # @param name [String]
      # @return [String, nil]
      def [](name); end
      # If name is the name of an environment variable, returns its value: ENV['foo'] = '0' ENV.fetch('foo') # => '0'
      # @param name [String]
      # @yieldparam [String] value
      def fetch(name, &block); end
      # Creates, updates, or deletes the named environment variable, returning the value.
      # @param name [String]
      # @param value [String, nil]
      # @return [String, nil]
      def []=(name, value); end
      # Creates, updates, or deletes the named environment variable, returning the value.
      # @param name [String]
      # @param value [String, nil]
      # @return [String, nil]
      def store(name, value); end
      # @yieldsplat
      # @yieldparam [String] value
      # @yieldparam [String] value
      def each(&block); end
      # @yieldsplat
      # @yieldparam [String] value
      # @yieldparam [String] value
      def each_pair(&block); end
      # @yieldparam [String] name
      def each_key(&block); end
      # @yieldparam [String] value
      def each_value(&block); end
      # Deletes the environment variable with name if it exists and returns its value: ENV['foo'] = '0' ENV.delete('foo') # => '0'
      # @param name [String]
      # @yieldparam [String] value
      def delete(name, &block); end
      # @yieldparam [String] name
      # @yieldparam [String] value
      def delete_if(&block); end
      # @yieldparam [String] name
      # @yieldparam [String] value
      def keep_if(&block); end
      # @return [Hash{String => String}]
      def slice(*names); end
      # Returns a hash except the given keys from ENV and their values.
      # @return [Hash{String => String}]
      def except(*names); end
      # Removes every environment variable; returns ENV: ENV.replace('foo' => '0', 'bar' => '1') ENV.size # => 2 ENV.clear # => ENV ENV.size # => 0
      # @return [self]
      def clear; end
      # Yields each environment variable name and its value as a 2-element Array.
      # @yieldparam [String] name
      # @yieldparam [String] value
      def reject(&block); end
      # Similar to ENV.delete_if, but returns nil if no changes were made.
      # @yieldparam [String] name
      # @yieldparam [String] value
      def reject!(&block); end
      # @yieldparam [String] name
      # @yieldparam [String] value
      def select(&block); end
      # @yieldparam [String] name
      # @yieldparam [String] value
      def filter(&block); end
      # @yieldparam [String] name
      # @yieldparam [String] value
      def select!(&block); end
      # @yieldparam [String] name
      # @yieldparam [String] value
      def filter!(&block); end
      # @return [Array, nil]
      def shift; end
      # @return [Hash{String => String}]
      def invert; end
      # Replaces the entire content of the environment variables with the name/value pairs in the given hash; returns ENV.
      # @param arg [Hash{String => String}]
      # @return [self]
      def replace(arg); end
      # @param arg [Hash{String => String, nil}]
      # @yieldparam [String] name
      # @yieldparam [String] env_val
      # @yieldparam [String, nil] hash_val
      # @return [self]
      def update(arg, &block); end
      # @param arg [Hash{String => String, nil}]
      # @yieldparam [String] name
      # @yieldparam [String] env_val
      # @yieldparam [String, nil] hash_val
      # @return [self]
      def merge!(arg, &block); end
      # (Provided for compatibility with Hash.)
      def rehash; end
      # @return [Array<Array>]
      def to_a; end
      # Returns String 'ENV': ENV.to_s # => "ENV"
      # @return [String]
      def to_s; end
      # Returns the name of the first environment variable with value, if it exists: ENV.replace('foo' => '0', 'bar' => '0') ENV.key('0') # => "foo"
      # @param value [String]
      # @return [String, nil]
      def key(value); end
      # Returns the count of environment variables: ENV.replace('foo' => '0', 'bar' => '1') ENV.length # => 2 ENV.size # => 2
      # @return [Integer]
      def size; end
      # Returns the count of environment variables: ENV.replace('foo' => '0', 'bar' => '1') ENV.length # => 2 ENV.size # => 2
      # @return [Integer]
      def length; end
      # Returns true when there are no environment variables, false otherwise: ENV.clear ENV.empty?
      # @return [Boolean]
      def empty?; end
      # Returns all variable names in an Array: ENV.replace('foo' => '0', 'bar' => '1') ENV.keys # => ['bar', 'foo']
      # @return [Array<String>]
      def keys; end
      # Returns all environment variable values in an Array: ENV.replace('foo' => '0', 'bar' => '1') ENV.values # => ['1', '0']
      # @return [Array<String>]
      def values; end
      # @return [Array<String, nil>]
      def values_at(*names); end
      # Returns true if there is an environment variable with the given name: ENV.replace('foo' => '0', 'bar' => '1') ENV.include?('foo') # => true
      # @param name [String]
      # @return [Boolean]
      def include?(name); end
      # Returns true if there is an environment variable with the given name: ENV.replace('foo' => '0', 'bar' => '1') ENV.include?('foo') # => true
      # @param name [String]
      # @return [Boolean]
      def member?(name); end
      # Returns true if there is an environment variable with the given name: ENV.replace('foo' => '0', 'bar' => '1') ENV.include?('foo') # => true
      # @param name [String]
      # @return [Boolean]
      def has_key?(name); end
      # @param value [String]
      # @return [Boolean]
      def has_value?(value); end
      # @param value [String]
      # @return [Boolean]
      def value?(value); end
      # Returns true if there is an environment variable with the given name: ENV.replace('foo' => '0', 'bar' => '1') ENV.include?('foo') # => true
      # @param name [String]
      # @return [Boolean]
      def key?(name); end
      # Returns a Hash containing all name/value pairs from ENV: ENV.replace('foo' => '0', 'bar' => '1') ENV.to_hash # => {"bar"=>"1", "foo"=>"0"}
      # @return [Hash{String => String}]
      def to_hash; end
      # @param name [String]
      # @return [Array, nil]
      def assoc(name); end
      # @param value [String]
      # @return [Array, nil]
      def rassoc(value); end
    end

